<?php
/**
 * NAMI CMS — Gallery
 *
 * Requires the "NAMI CMS — Core engine" snippet, version 1.2.0 or later
 * (collections). Adds a "Gallery" menu:
 *   - All Moments / Add New: each photo, video or quote card on /gallery.
 *   - Add Many Photos: pick several photos at once and file them together.
 *   - Page: …: the heading, the institution tabs and the bubbles under each tab.
 *
 * Field keys must match src/lib/cms/pages/gallery/types.ts in the Next.js project.
 * The JSON blocks at the bottom are generated by `npm run cms:defaults`.
 */

if ( ! defined( 'ABSPATH' ) ) {
	return;
}

function nami_gallery_institutions() {
	return array(
		'all'              => 'All of NAMI (shows under every tab)',
		'primary'          => 'Primary',
		'higher-secondary' => '+2 Higher Secondary',
		'a-levels'         => 'A-Levels',
		'bachelors'        => 'Bachelors & Masters',
	);
}

function nami_gallery_categories() {
	return array(
		'academics'    => 'Academics',
		'campus-life'  => 'Campus Life',
		'events'       => 'Events',
		'sports'       => 'Sports',
		'achievements' => 'Achievements',
		'all'          => 'General',
	);
}

/** Bubble choices come from Gallery → Page: … so new bubbles appear here at once. */
function nami_gallery_bubble_options() {
	$options = array( '' => '— None —' );
	if ( ! function_exists( 'nami_cms_get_values' ) ) {
		return $options;
	}
	$values = nami_cms_get_values( 'gallery' );
	$groups = array(
		'primary'   => 'Primary',
		'plusTwo'   => '+2',
		'aLevels'   => 'A-Levels',
		'bachelors' => 'Bachelors',
	);
	foreach ( $groups as $section => $name ) {
		$bubbles = $values[ $section ]['bubbles'] ?? array();
		foreach ( is_array( $bubbles ) ? $bubbles : array() as $bubble ) {
			$key = trim( (string) ( $bubble['key'] ?? '' ) );
			if ( '' === $key || 'all' === $key ) {
				continue;
			}
			$label           = $name . ': ' . (string) ( $bubble['label'] ?? $key );
			$options[ $key ] = isset( $options[ $key ] ) ? $options[ $key ] . ' / ' . $label : $label;
		}
	}
	return $options;
}

