/* ------------------------------------------------------------------
 * Gallery → Add Many Photos
 * ------------------------------------------------------------------ */

add_action(
	'admin_menu',
	function () {
		$hook = add_submenu_page(
			'edit.php?post_type=nami_gallery',
			'Add Many Photos',
			'Add Many Photos',
			'edit_pages',
			'nami-gallery-bulk',
			'nami_gallery_render_bulk'
		);
		add_action(
			'admin_enqueue_scripts',
			function ( $current ) use ( $hook ) {
				if ( $current === $hook ) {
					wp_enqueue_media();
				}
			}
		);
	},
	20
);

function nami_gallery_select( $name, array $options, $selected = '' ) {
	$html = sprintf( '<select name="%s" id="%s">', esc_attr( $name ), esc_attr( $name ) );
	foreach ( $options as $value => $label ) {
		$html .= sprintf( '<option value="%s"%s>%s</option>', esc_attr( $value ), selected( (string) $selected, (string) $value, false ), esc_html( $label ) );
	}
	return $html . '</select>';
}

function nami_gallery_render_bulk() {
	$added = isset( $_GET['nami_added'] ) ? absint( $_GET['nami_added'] ) : null;
	echo '<div class="wrap"><h1>Add Many Photos</h1>';
	if ( null !== $added ) {
		printf(
			'<div class="notice notice-success is-dismissible"><p>%s <a href="%s">See all moments</a></p></div>',
			esc_html( sprintf( '%d photo%s added to the gallery.', $added, 1 === $added ? '' : 's' ) ),
			esc_url( admin_url( 'edit.php?post_type=nami_gallery' ) )
		);
	}
	echo '<p style="max-width:720px">Choose or upload several photos, pick where they belong, and add them in one go. Each photo becomes its own moment; its caption is the photo\'s title in the Media Library (you can change it afterwards).</p>';
	echo '<form method="post" action="' . esc_url( admin_url( 'admin-post.php' ) ) . '">';
	echo '<input type="hidden" name="action" value="nami_gallery_bulk">';
	wp_nonce_field( 'nami_gallery_bulk' );
	echo '<input type="hidden" name="photos" id="nami-bulk-photos" value="[]">';
	echo '<table class="form-table" role="presentation"><tbody>';
	echo '<tr><th scope="row">Photos</th><td><p><button type="button" class="button button-primary" id="nami-bulk-pick">Choose / upload photos</button></p><div id="nami-bulk-preview" style="display:flex;flex-wrap:wrap;gap:8px;margin-top:8px"></div><p class="description" id="nami-bulk-count">No photos chosen yet.</p></td></tr>';
	echo '<tr><th scope="row"><label for="institution">Tab</label></th><td>' . nami_gallery_select( 'institution', nami_gallery_institutions(), 'all' ) . '</td></tr>'; // phpcs:ignore WordPress.Security.EscapeOutput
	echo '<tr><th scope="row"><label for="category">Category</label></th><td>' . nami_gallery_select( 'category', nami_gallery_categories(), 'events' ) . '</td></tr>'; // phpcs:ignore WordPress.Security.EscapeOutput
	echo '<tr><th scope="row"><label for="bubble">Bubble</label></th><td>' . nami_gallery_select( 'bubble', nami_gallery_bubble_options() ) . '</td></tr>'; // phpcs:ignore WordPress.Security.EscapeOutput
	echo '<tr><th scope="row"><label for="caption">Caption (optional)</label></th><td><input type="text" class="regular-text" name="caption" id="caption"><p class="description">Used for every photo instead of its Media Library title, e.g. "Sports Week 2026".</p></td></tr>';
	echo '</tbody></table>';
	submit_button( 'Add photos to the gallery' );
	echo '</form></div>';
	?>
	<script>
	(function () {
		var chosen = [];
		var input = document.getElementById('nami-bulk-photos');
		var preview = document.getElementById('nami-bulk-preview');
		var count = document.getElementById('nami-bulk-count');
		document.getElementById('nami-bulk-pick').addEventListener('click', function (event) {
			event.preventDefault();
			var frame = wp.media({ title: 'Choose photos', library: { type: 'image' }, button: { text: 'Use these photos' }, multiple: 'add' });
			frame.on('select', function () {
				chosen = frame.state().get('selection').toJSON().map(function (file) {
					return { id: file.id, url: file.url, alt: file.alt || '', title: file.title || '', width: file.width || 0, height: file.height || 0 };
				});
				input.value = JSON.stringify(chosen);
				preview.innerHTML = '';
				chosen.forEach(function (file) {
					var img = document.createElement('img');
					img.src = file.url;
					img.alt = '';
					img.style.cssText = 'width:96px;height:72px;object-fit:cover;border-radius:4px;border:1px solid #dcdcde';
					preview.appendChild(img);
				});
				count.textContent = chosen.length + ' photo' + (chosen.length === 1 ? '' : 's') + ' chosen.';
			});
			frame.open();
		});
	})();
	</script>
	<?php
}

add_action(
	'admin_post_nami_gallery_bulk',
	function () {
		check_admin_referer( 'nami_gallery_bulk' );
		if ( ! current_user_can( 'edit_pages' ) || ! function_exists( 'nami_cms_collections' ) ) {
			wp_die( 'You are not allowed to add photos.', 403 );
		}
		$config = nami_cms_collections()['gallery-items'] ?? null;
		if ( null === $config ) {
			wp_die( 'The gallery is not set up.', 500 );
		}

		$photos  = json_decode( wp_unslash( (string) ( $_POST['photos'] ?? '[]' ) ), true ); // phpcs:ignore WordPress.Security.ValidatedSanitizedInput -- each value sanitised below.
		$caption = sanitize_text_field( wp_unslash( $_POST['caption'] ?? '' ) );
		$shared  = array(
			'type'        => 'image',
			'institution' => wp_unslash( $_POST['institution'] ?? 'all' ),
			'category'    => wp_unslash( $_POST['category'] ?? 'all' ),
			'bubble'      => wp_unslash( $_POST['bubble'] ?? '' ),
		);
		$added   = 0;
		$GLOBALS['nami_cms_quiet'] = true;

		foreach ( is_array( $photos ) ? array_slice( $photos, 0, 200 ) : array() as $photo ) {
			if ( ! is_array( $photo ) || ! wp_attachment_is_image( absint( $photo['id'] ?? 0 ) ) ) {
				continue;
			}
			$id      = absint( $photo['id'] );
			$title   = '' !== $caption ? $caption : sanitize_text_field( (string) get_the_title( $id ) );
			$alt     = (string) get_post_meta( $id, '_wp_attachment_image_alt', true );
			$meta    = wp_get_attachment_metadata( $id );
			$post_id = wp_insert_post(
				array(
					'post_type'   => 'nami_gallery',
					'post_status' => 'publish',
					'post_title'  => '' !== $title ? $title : 'Photo',
				),
				true
			);
			if ( is_wp_error( $post_id ) ) {
				continue;
			}
			$fields = nami_cms_collection_clean(
				$config,
				array_merge(
					$shared,
					array(
						'image' => array(
							'src'    => wp_get_attachment_url( $id ),
							'alt'    => '' !== $alt ? $alt : $title,
							'width'  => $meta['width'] ?? 0,
							'height' => $meta['height'] ?? 0,
						),
					)
				)
			);
			update_post_meta( $post_id, '_nami_fields', wp_slash( $fields ) );
			++$added;
		}

		$GLOBALS['nami_cms_quiet'] = false;
		if ( $added > 0 ) {
			nami_cms_notify_site( 'gallery-items' );
		}
		wp_safe_redirect( admin_url( 'edit.php?post_type=nami_gallery&page=nami-gallery-bulk&nami_added=' . $added ) );
		exit;
	}
);
